    #[test]
    fn level_two_authored_class14_model5_scans_past_remote_collision_for_local_xp() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 authored class-14 session");
        let source = session
            .allocate_level2_authored_class14(248)
            .expect("authored subtype-5 row");
        session
            .shared_spells_mut()
            .acquire_level2_spell_holder(12, PhysicalSpellActionRole::OrdinaryPickup, true)
            .expect("source-shaped family-12 acquisition");
        let source_slot = source.source_entity_index;
        let scroll_position = source.position;
        let remote_entity_index = session
            .shared_spells()
            .players
            .iter()
            .find(|player| player.slot == 1)
            .expect("remote Level 2 player")
            .entity_index;
        let remote = session
            .entities
            .iter_mut()
            .find(|entity| entity.index == remote_entity_index)
            .expect("remote player entity");
        remote.position = scroll_position;
        // The reset package's remote player is a model-1 source row. The
        // source scroll callback only admits model-0 players, so this
        // discriminating candidate is normalized to the live model-0 shape
        // before the source-order scan.
        remote.model = 0;
        session.state.position = scroll_position;
        // The owner package orders local then remote. Reversing only the
        // player cursor makes the remote overlap the first candidate and
        // proves the source scan does not return before the local player.
        session.shared_spells_mut().players.swap(0, 1);
        let before = session.shared_spells().spell_experience()[12];

        session.step_outer_turn(PlayerCommand::default(), 0);

        assert_eq!(
            session.shared_spells().spell_experience()[12],
            before + LEVEL2_EXPERIENCE_SCROLL_AWARD
        );
        assert!(
            session
                .shared_spells()
                .pickup_events()
                .iter()
                .any(|event| matches!(
                    event,
                    Level2SharedSpellEvent::ExperienceScrollCollected {
                        source_slot: observed,
                        player_entity_index,
                    } if *observed == source_slot && *player_entity_index == remote_entity_index
                ))
        );
        assert!(session.economy().free_slots.contains(&source_slot));
    }

    #[test]
    fn level_two_authored_model13_runs_source_callback_and_spawn_branch() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 authored model-13 session");
        let baseline_hash = session.campaign_state_hash();

        let source = session
            .allocate_level2_authored_model13(365)
            .expect("authored model-13 row 365");
        assert_eq!(
            (
                source.entity_id,
                source.source_class,
                source.model,
                source.action,
                source.subspell_index,
                source.max_life,
                source.life,
                source.particle_index,
                source.control_flags,
                source.shift_rot_x,
                source.shift_rot_y,
            ),
            (
                source.source_entity_index,
                10,
                19,
                19,
                200,
                240,
                240,
                228,
                0x0002_0001,
                512,
                512,
            )
        );

        // Pick a source RNG whose first SEARCH.DAT cell takes the source's
        // emitting branch, then force life=2 so the post-decrement life is
        // odd and the source emits its four yaw phases.
        let seed = (1..=u16::MAX)
            .find(|candidate| level2_next_rng16(*candidate) % 0x9d >= 79)
            .expect("a model-13 emitting RNG seed exists");
        let parent = session
            .economy_mut()
            .authored_model13
            .iter_mut()
            .find(|candidate| candidate.source_entity_index == source.source_entity_index)
            .expect("model-13 parent remains live");
        parent.life = 2;
        parent.entity_rng = seed;
        assert!(
            session
                .economy_mut()
                .step_authored_model13_slot(source.source_entity_index)
        );
        let stepped_parent = session
            .economy()
            .authored_model13()
            .iter()
            .find(|candidate| candidate.source_entity_index == source.source_entity_index)
            .copied()
            .expect("model-13 parent survives first callback");
        assert_eq!(stepped_parent.life, 1);
        assert_eq!(stepped_parent.dword_0x10, 0);
        let child_count = session.economy().model13_spawned_children().len();
        assert!(child_count >= 4 && child_count % 4 == 0);
        assert!(
            session
                .economy()
                .model13_spawned_children()
                .iter()
                .all(|child| {
                    child.parent_entity_index == source.source_entity_index
                        && child.parent_entity_id == source.entity_id
                        && (child.model, child.action, child.source_class) == (14, 14, 10)
                        && child.max_life == child.life
                        && child.entity_index == 9
                        && child.subtype == 14
                })
        );
        let child = session.economy().model13_spawned_children()[0];
        assert!(
            session
                .economy_mut()
                .step_model13_spawned_child_slot(child.source_entity_index)
        );
        let stepped_child = session
            .economy()
            .model13_spawned_children()
            .iter()
            .find(|candidate| candidate.source_entity_index == child.source_entity_index)
            .copied()
            .expect("model-13 child survives first callback");
        assert_eq!(
            stepped_child.actual_speed,
            child.actual_speed.saturating_sub(4).max(64)
        );
        assert!(stepped_child.position.z >= child.position.z);

        let saved_free_slots = session.economy().free_slots.clone();
        session.economy_mut().free_slots.clear();
        assert!(session.allocate_level2_authored_model13(366).is_none());
        session.economy_mut().free_slots = saved_free_slots;

        session
            .economy_mut()
            .authored_model13
            .iter_mut()
            .find(|candidate| candidate.source_entity_index == source.source_entity_index)
            .expect("model-13 parent for expiry")
            .life = -1;
        assert!(
            session
                .economy_mut()
                .step_authored_model13_slot(source.source_entity_index)
        );
        let expired = session
            .economy()
            .authored_model13()
            .iter()
            .find(|candidate| candidate.source_entity_index == source.source_entity_index)
            .copied()
            .expect("model-13 terminal row remains hidden in the source arena");
        assert!(expired.active);
        assert!(!expired.drawing_enabled);
        session.economy_mut().reclaim_inactive_slots();
        assert!(
            session
                .economy()
                .authored_model13()
                .iter()
                .any(|candidate| candidate.source_entity_index == source.source_entity_index)
        );

        session.reset();
        assert!(session.economy().authored_model13().is_empty());
        assert!(session.economy().model13_spawned_children().is_empty());
        assert_eq!(session.campaign_state_hash(), baseline_hash);
    }

    #[test]
    fn level_two_bee_action17_moves_before_acquisition_rng() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 Bee movement session");
        let source = session
            .allocate_level2_authored_bee(210)
            .expect("authored Day Bee row 210");
        let mut configured = source;
        configured.position = Position {
            x: 0x1000,
            y: 0x1010,
            z: 0,
        };
        configured.yaw = 0;
        configured.roll = 0;
        configured.source_byte_3e = 0;
        configured.source_byte_39 = 0;
        configured.control_flags = 8;
        configured.entity_rng = 0x1234;
        assert!(session.economy.replace_authored_bee_for_test(configured));

        let ground = session.economy.terrain.ground_height(configured.position);
        let mut expected_position = configured.position;
        if expected_position.z > ground {
            expected_position.z = expected_position
                .z
                .wrapping_add(LEVEL2_BEE_GROUND_RELAXATION);
        }
        if expected_position.z <= ground.wrapping_add(LEVEL2_BEE_GROUND_CLEARANCE) {
            expected_position.z = ground.wrapping_add(LEVEL2_BEE_GROUND_CLEARANCE);
        }
        crate::move_entity(
            &mut expected_position,
            configured.yaw,
            0,
            configured.actual_speed,
        );
        let first = level2_next_rng16(configured.entity_rng);
        let second = level2_next_rng16(first);
        let direction = 2 * (u32::from(first % 0x9d) / 79);
        let expected_roll = (i32::from(configured.roll)
            + (i32::from((second & 0xff) as u8) + 85)
                * (i32::try_from(direction).expect("Bee roll direction fits") - 1))
            as i16
            & 0x07ff;

        // The cadence is active, but byte_0x39 suppresses only the target
        // scan. The source must still move first and consume both wander
        // draws after that movement.
        assert!(
            session
                .economy
                .acquire_authored_bee_target(configured.source_entity_index, &[])
                .is_none()
        );
        let moved = session
            .economy
            .authored_bees
            .iter()
            .find(|bee| bee.source_entity_index == configured.source_entity_index)
            .copied()
            .expect("action-17 Bee remains live");
        assert_eq!(moved.position, expected_position);
        assert_eq!(moved.entity_rng, second);
        assert_eq!(moved.roll, expected_roll);
        assert_eq!(moved.control_flags, 8);
        assert_eq!(moved.action, 17);
    }

    #[test]
    fn level_two_bee_action17_blocked_heading_retries_source_order() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 Bee retry session");
        let source = session
            .allocate_level2_authored_bee(210)
            .expect("authored Day Bee row 210");
        let mut configured = source;
        configured.position = Position {
            x: 0x20f0,
            y: 0x1010,
            z: 0,
        };
        configured.yaw = 0;
        configured.roll = 0;
        configured.source_byte_3e = 1;
        configured.source_byte_39 = 0;
        configured.control_flags = 8;
        assert!(session.economy.replace_authored_bee_for_test(configured));

        let headings = level2_bee_retry_headings(configured.yaw);
        let candidate_tile = |heading: i16| {
            let mut candidate = configured.position;
            crate::move_entity(&mut candidate, heading, 0, configured.actual_speed);
            level2_bee_source_tile(candidate)
        };
        let first_tile = candidate_tile(headings[0]);
        let second_tile = candidate_tile(headings[1]);
        assert_ne!(
            first_tile, second_tile,
            "retry candidates must cross distinct tiles"
        );

        // Give the first candidate a source-slope rejection while leaving the
        // second candidate flat. The shared edge is kept at 255 so the first
        // tile's diagonal remains steep and the second tile remains level.
        let (first_x, first_y) = first_tile;
        let (second_x, second_y) = second_tile;
        for (x, y) in [
            (second_x, second_y),
            (second_x.wrapping_add(1), second_y),
            (second_x.wrapping_add(1), second_y.wrapping_add(1)),
            (second_x, second_y.wrapping_add(1)),
        ] {
            session.economy.terrain.planes.ground_heights[terrain_index(x, y)] = 255;
        }
        for (x, y, height) in [
            (first_x, first_y, 0),
            (first_x.wrapping_add(1), first_y, 255),
            (first_x.wrapping_add(1), first_y.wrapping_add(1), 255),
            (first_x, first_y.wrapping_add(1), 0),
        ] {
            session.economy.terrain.planes.ground_heights[terrain_index(x, y)] = height;
        }

        let mut expected_position = configured.position;
        let ground = session.economy.terrain.ground_height(expected_position);
        if expected_position.z > ground {
            expected_position.z = expected_position
                .z
                .wrapping_add(LEVEL2_BEE_GROUND_RELAXATION);
        }
        if expected_position.z <= ground.wrapping_add(LEVEL2_BEE_GROUND_CLEARANCE) {
            expected_position.z = ground.wrapping_add(LEVEL2_BEE_GROUND_CLEARANCE);
        }
        crate::move_entity(
            &mut expected_position,
            headings[1],
            0,
            configured.actual_speed,
        );
        let expected_yaw =
            headings[1].wrapping_add(level2_bee_turn_delta(headings[1], configured.roll)) & 0x07ff;

        // Non-cadence still exercises the movement prelude but consumes no
        // wander RNG, isolating retry order from acquisition bookkeeping.
        assert!(
            session
                .economy
                .acquire_authored_bee_target(configured.source_entity_index, &[])
                .is_none()
        );
        let retried = session
            .economy
            .authored_bees
            .iter()
            .find(|bee| bee.source_entity_index == configured.source_entity_index)
            .copied()
            .expect("retried Bee remains live");
        assert_eq!(retried.position, expected_position);
        assert_eq!(retried.yaw, expected_yaw);
        assert_ne!(retried.control_flags & LEVEL2_BEE_OBSTRUCTION_BIT, 0);
        assert_eq!(retried.entity_rng, configured.entity_rng);
    }

